    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                pr, pc = r-dr, c-dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                # Start of a diagonal run; collect its contiguous cells.
                run = []
                rr, cc = r, c
                while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    run.append((rr, cc))
                    rr += dr; cc += dc
                if len(run) < 2:
                    continue
                # Extend the run in both directions through the background.
                for sr, sc, vr, vc in ((r-dr, c-dc, -dr, -dc), (rr, cc, dr, dc)):
